def total_travel_distance(points):
    """
    Calculate the total travel distance for a round-trip path over a list of
    2D coordinates. The path starts at the first point, visits each
    consecutive point in order, and returns to the starting point.

    Points that contain just one number are treated as (n, n).

    Returns 0.0 if the list is empty or contains only one point.
    """
    if not points or len(points) == 1:
        return 0.0

    # Normalize points: if a point contains just one number, both
    # coordinates are assumed equal to this number.
    normalized = []
    for p in points:
        if len(p) == 1:
            normalized.append((p[0], p[0]))
        else:
            normalized.append(tuple(p))

    total = 0.0
    n = len(normalized)
    for i in range(n):
        a = normalized[i]
        b = normalized[(i + 1) % n]  # wraps around back to the first point
        total += distance.euclidean(a, b)
    return float(total)
